function problemFor(spec: TrickSpec) {
  return makeProblem(
    `When should you use this trick: ${spec.name}?`,
    'A',
    [spec.when, 'Whenever a choice looks longest', 'Only after solving the standard way', 'Only on questions you plan to skip'],
    spec.why,
  )
}

function toLevel(index: number, spec: TrickSpec): StudyLevel {
  const category = spec.section.includes('Science') ? 'ACT Science Tricks'
    : spec.section.includes('Reading') && spec.test === 'ACT' ? 'ACT Reading Tricks'
      : spec.section.includes('English') ? 'ACT English Tricks'
        : spec.section.includes('Reading & Writing') ? 'SAT Reading & Writing Tricks'
          : spec.test === 'ACT' ? 'ACT Math Tricks'
            : spec.test === 'SAT' ? 'SAT Math Tricks'
              : 'Universal Test Tricks'
  return makeLevel(
    index,
    spec.track,
    category,
    spec.name,
    [spec.test.toLowerCase(), spec.section.toLowerCase(), ...spec.tags, spec.name.toLowerCase()],
    spec.example,
    [`When ${spec.when}, use ${spec.trick} because ${spec.why}`],
    [
      `Test: ${spec.test}`,
      `Section: ${spec.section}`,
      `When to Use It: ${spec.when}`,
      `The Trick: ${spec.trick}`,
      `Why It Works: ${spec.why}`,
      `Example: ${spec.example}`,
      `Fast Method: ${spec.fast}`,
      `Watch Out: ${spec.watch}`,
    ],
    [problemFor(spec)],
    {
      subcategory: category,
      scope: spec.test === 'SAT' ? 'sat_strategy' : spec.test === 'ACT' ? 'act_strategy' : 'both_strategy',
      tested: 'strategy',
      objectives: [spec.trick],
      difficulty: 'hard',
    },
  )
}

export function buildTrickStrategyLevels(startIndex: number, track: StudyTrack): StudyLevel[] {
  let i = startIndex
  return SPECS
    .filter((spec) => spec.track === track)
    .map((spec) => toLevel(i++, spec))
}
